const assertServiceId = (value) => {
  const text = String(value ?? '').trim();
  if (!/^[0-9]+$/.test(text)) {
    throw new Error(`Invalid service_id: ${value}`);
  }
  return text;
};

const input = $input.first().json;
const body = input.body ?? input;
return [{ json: { service_id: assertServiceId(body.service_id) } }];

// El borrado en Drive es best-effort: la fila ya quedó limpia, que es lo que
// ve el usuario. Un archivo huérfano en Drive no justifica devolver un error.
const cleared = $('Limpiar en service_catalog').first().json;

if (!cleared || cleared.error || !cleared.id) {
  return [{ json: { statusCode: 500, body: { message: 'No se pudo quitar la imagen.' } } }];
}

return [{ json: { statusCode: 200, body: { success: true, service_id: cleared.id } } }];
